  aroom A1 vm1 (kR - RK_deser) (bR - RB_deser) -> (RK_deser <= kR)%Z -> (RB_deser <= bR)%Z ->
  (s mod 16 = 0)%Z -> (c_top C - LSTK + 256 + LSF <= s)%Z -> (s <= c_top C)%Z -> ret_ok ret -> getr regs 2 = Z_to_bv 64 s ->
